import * as Sentry from "@sentry/nextjs";
import React, { useEffect, useState } from "react";
import { details } from "./representativeDetails";
import { inputCls, pillCls } from "@/components/profile-page/fieldStyles";
import getLocations from "@/services/locations";

/** Soru (sol) + cevap alanı (sağ) iki sütunlu satır. */
const QaRow = ({
  question,
  hint,
  children,
}: {
  question: string;
  hint?: string;
  children: React.ReactNode;
}) => (
  <div className="tw-grid tw-gap-3 tw-border-0 tw-border-b tw-border-solid tw-border-[#ece9f1] tw-py-4 md:tw-grid-cols-2 md:tw-gap-8">
    <p className="tw-m-0 tw-text-sm tw-font-semibold tw-text-[#14101c]">
      {question}
      {hint && (
        <span className="tw-ml-1 tw-font-normal tw-text-[#8b8397]">{hint}</span>
      )}
    </p>
    <div>{children}</div>
  </div>
);

/** Birden çok seçilebilen checkbox grubu → pill'ler (formData.questions[code] === true). */
const CheckPillGroup = ({
  items,
  formData,
  onFilterChange,
}: {
  items: any[];
  formData: any;
  onFilterChange: any;
}) => (
  <div className="tw-flex tw-flex-wrap tw-gap-2">
    {items.map((detail: any) => {
      const checked = formData.questions[detail.code] === true;
      return (
        <label key={detail.name} className={pillCls(checked)}>
          <input
            type="checkbox"
            className="tw-sr-only"
            checked={checked}
            onChange={(e) =>
              onFilterChange({
                ...formData,
                questions: {
                  ...formData.questions,
                  [detail.code]: e.target.checked,
                },
              })
            }
          />
          {detail.name}
        </label>
      );
    })}
  </div>
);

/** Yes / No pill ikilisi. */
const YesNoPills = ({
  value,
  onChange,
}: {
  value: string;
  onChange: (v: string) => void;
}) => (
  <div className="tw-flex tw-gap-2">
    {[
      { v: "yes", label: "Yes" },
      { v: "no", label: "No" },
    ].map((o) => (
      <button
        type="button"
        key={o.v}
        className={pillCls(value === o.v)}
        onClick={() => onChange(o.v)}
      >
        {o.label}
      </button>
    ))}
  </div>
);

/** +/- sayaç. */
const Counter = ({
  value,
  onDecrease,
  onIncrease,
}: {
  value: number;
  onDecrease: () => void;
  onIncrease: () => void;
}) => (
  <div className="tw-inline-flex tw-items-center tw-overflow-hidden tw-rounded-lg tw-border tw-border-solid tw-border-[#d6d2de]">
    <button
      type="button"
      onClick={onDecrease}
      className="tw-flex tw-h-10 tw-w-10 tw-cursor-pointer tw-items-center tw-justify-center tw-border-0 tw-bg-[#faf8ff] tw-text-lg tw-font-bold tw-text-[#854ec9] tw-transition hover:tw-bg-[#ece9f1]"
    >
      −
    </button>
    <span className="tw-flex tw-h-10 tw-min-w-[3.5rem] tw-items-center tw-justify-center tw-text-sm tw-font-semibold tw-text-[#14101c]">
      {value}
    </span>
    <button
      type="button"
      onClick={onIncrease}
      className="tw-flex tw-h-10 tw-w-10 tw-cursor-pointer tw-items-center tw-justify-center tw-border-0 tw-bg-[#faf8ff] tw-text-lg tw-font-bold tw-text-[#854ec9] tw-transition hover:tw-bg-[#ece9f1]"
    >
      +
    </button>
  </div>
);

const CheckboxForm = ({
  formData,
  onFilterChange,
}: {
  formData: any;
  onFilterChange: any;
}) => {
  const [value1, setValue1] = useState(0);
  const [value2, setValue2] = useState(0);
  const [value3, setValue3] = useState(0);
  const [selectedValues1, setSelectedValues1] = useState<string[]>([]);
  const numberOfSelects = 5;
  const [countries, setCountries] = useState([]);

  const increaseValue1 = () => {
    setValue1(value1 + 1);
    setSelectedValues1([...selectedValues1, ""]);
    onFilterChange({
      ...formData,
      questions: {
        ...formData.questions,
        how_many_office_you_own: value1 + 1,
      },
    });
  };

  const decreaseValue1 = () => {
    if (value1 > 0) {
      setValue1(value1 - 1);
      setSelectedValues1(selectedValues1.slice(0, -1));
      onFilterChange({
        ...formData,
        questions: {
          ...formData.questions,
          how_many_office_you_own: value1 - 1,
        },
      });
    }
  };

  const handleSelectChange1 = (
    index: number,
    event: React.ChangeEvent<HTMLSelectElement>
  ) => {
    const updatedValues = [...selectedValues1];
    updatedValues[index] = event.target.value;
    setSelectedValues1(updatedValues);
    onFilterChange({
      ...formData,
      questions: {
        ...formData.questions,
        ["if_more_than_one_how_many_different_countries.undefined.row." +
        index +
        ".which_country"]: parseInt(event.target.value),
      },
    });
  };

  const increaseValue2 = () => {
    setValue2(value2 + 1);
    onFilterChange({
      ...formData,
      questions: {
        ...formData.questions,
        how_many_people_work_in_your_office: value2 + 1,
      },
    });
  };

  const decreaseValue2 = () => {
    if (value2 > 0) {
      setValue2(value2 - 1);
      onFilterChange({
        ...formData,
        questions: {
          ...formData.questions,
          how_many_people_work_in_your_office: value2 + 1,
        },
      });
    }
  };

  const increaseValue3 = () => {
    setValue3(value3 + 1);
    onFilterChange({
      ...formData,
      questions: {
        ...formData.questions,
        if_yes_have_many_active_tour_itinerary_on_your_website: value3 + 1,
      },
    });
  };

  const decreaseValue3 = () => {
    if (value3 > 0) {
      setValue3(value3 - 1);
      onFilterChange({
        ...formData,
        questions: {
          ...formData.questions,
          if_yes_have_many_active_tour_itinerary_on_your_website: value3 - 1,
        },
      });
    }
  };

  useEffect(() => {
    const fetchCountries = async () => {
      try {
        setCountries((await getLocations()) || []);
      } catch (error) {
        Sentry.captureException(error);
      }
    };
    fetchCountries();
  }, []);

  const setQuestion = (key: string, val: any) =>
    onFilterChange({
      ...formData,
      questions: { ...formData.questions, [key]: val },
    });

  /** which_countries / which_coutries... için 5x3 (ülke/pax/bütçe) select ızgarası. */
  const SpecializationGrid = ({ prefix }: { prefix: string }) => (
    <div className="tw-grid tw-grid-cols-1 tw-gap-3 sm:tw-grid-cols-3">
      <div className="tw-space-y-2">
        {Array.from({ length: numberOfSelects }, (_, index) => (
          <select
            key={index}
            className={inputCls}
            onChange={(e) =>
              setQuestion(
                `${prefix}.undefined.row.${index}.which_country`,
                parseInt(e.target.value)
              )
            }
          >
            <option value="">Which country</option>
            {countries.map((country: any) => (
              <option key={country.id} value={country.id}>
                {country.name}
              </option>
            ))}
          </select>
        ))}
      </div>
      <div className="tw-space-y-2">
        {Array.from({ length: numberOfSelects }, (_, index) => (
          <select
            key={index}
            className={inputCls}
            onChange={(e) =>
              setQuestion(
                `${prefix}.undefined.row.${index}.approximate_pax`,
                parseInt(e.target.value)
              )
            }
          >
            <option>Approximate Pax</option>
            {details[0].pax.map((detail: any) => (
              <option key={detail.name} value={detail.selectValue}>
                {detail.name}
              </option>
            ))}
          </select>
        ))}
      </div>
      <div className="tw-space-y-2">
        {Array.from({ length: numberOfSelects }, (_, index) => (
          <select
            key={index}
            className={inputCls}
            onChange={(e) =>
              setQuestion(
                `${prefix}.undefined.row.${index}.approximate_budget`,
                parseInt(e.target.value)
              )
            }
          >
            <option>Approximate Budget</option>
            {details[0].budget.map((detail: any) => (
              <option key={detail.name} value={detail.selectValue}>
                {detail.name}
              </option>
            ))}
          </select>
        ))}
      </div>
    </div>
  );

  const checkboxSections: { title: string; items: any[] }[] = [
    { title: "ADVENTURE & SPORT TOURISM", items: details[0].sports },
    { title: "BEACH TOURISM", items: details[0].beachTourism },
    { title: "CRUISE TOURISM", items: details[0].cruiseTourism },
    { title: "EVENT TOURISM", items: details[0].eventTourism },
    {
      title: "HISTORICAL AND CULTURAL TOUR",
      items: details[0].historicalCultural,
    },
    { title: "MEDICAL & WELLNESS TOURISM", items: details[0].medicalWellness },
    { title: "ECO TOURISM & RESPONSIBLE TRAVEL", items: details[0].ecoTourism },
    { title: "SPECIAL OCCASION TOUR", items: details[0].specialOccasion },
    { title: "TRANSPORTATION & RENTAL", items: details[0].transportation },
  ];

  return (
    <div>
      <QaRow question="What Type of Company You are?">
        <CheckPillGroup
          items={details[0].companyType}
          formData={formData}
          onFilterChange={onFilterChange}
        />
      </QaRow>

      <QaRow question="What Types of Tourism Businesses you operate?">
        <div className="tw-flex tw-flex-wrap tw-gap-2">
          {details[0].typeBusinesses.map((detail: any) => {
            const active =
              formData.questions[detail.code] === detail.selectedValue;
            return (
              <button
                type="button"
                key={detail.name}
                className={pillCls(active)}
                onClick={() => setQuestion(detail.code, detail.selectedValue)}
              >
                {detail.name}
              </button>
            );
          })}
        </div>
      </QaRow>

      <QaRow question="Do you have a proper and working web page of your own?">
        <YesNoPills
          value={
            formData.questions.do_you_have_a_proper_and_working_web_page_of_your_own
          }
          onChange={(v) =>
            setQuestion(
              "do_you_have_a_proper_and_working_web_page_of_your_own",
              v
            )
          }
        />
      </QaRow>

      {formData.questions
        .do_you_have_a_proper_and_working_web_page_of_your_own === "yes" && (
        <QaRow question="If yes, have many active tour itinerary on your website">
          <Counter
            value={value3}
            onDecrease={decreaseValue3}
            onIncrease={increaseValue3}
          />
        </QaRow>
      )}

      <QaRow question="How many offices you own?">
        <Counter
          value={value1}
          onDecrease={decreaseValue1}
          onIncrease={increaseValue1}
        />
        {selectedValues1.length > 0 && (
          <div className="tw-mt-3 tw-space-y-2">
            {selectedValues1.map((selectedValue1, index) => (
              <select
                className={`${inputCls} tw-max-w-sm`}
                key={index}
                value={selectedValue1}
                onChange={(e) => handleSelectChange1(index, e)}
              >
                <option value="">Which country</option>
                {countries.map((country: any) => (
                  <option key={country.id} value={country.id}>
                    {country.name}
                  </option>
                ))}
              </select>
            ))}
          </div>
        )}
      </QaRow>

      <QaRow question="How many people work in your office?">
        <Counter
          value={value2}
          onDecrease={decreaseValue2}
          onIncrease={increaseValue2}
        />
      </QaRow>

      <QaRow question="Do you have an outgoing department right now?">
        <YesNoPills
          value={formData.questions.do_you_have_an_ongoing_department_right_now}
          onChange={(v) =>
            setQuestion("do_you_have_an_ongoing_department_right_now", v)
          }
        />
      </QaRow>

      <QaRow
        question="Which countries are you specialized in?"
        hint="If more than 10, please type only main 10"
      >
        <SpecializationGrid prefix="which_countries_are_you_specialized_in" />
      </QaRow>

      <QaRow question="Do you have an Incoming department right now?">
        <YesNoPills
          value={formData.questions.do_you_have_an_incoming_department_right_now}
          onChange={(v) =>
            setQuestion("do_you_have_an_incoming_department_right_now", v)
          }
        />
      </QaRow>

      <QaRow
        question="Which countries are you specialized to receive customers from?"
        hint="Please type only main 10"
      >
        <SpecializationGrid prefix="which_coutries_are_you_specialized_to_received_customers" />
      </QaRow>

      {checkboxSections.map((section) => (
        <QaRow key={section.title} question={section.title}>
          <CheckPillGroup
            items={section.items}
            formData={formData}
            onFilterChange={onFilterChange}
          />
        </QaRow>
      ))}

      <QaRow question="OTHERS">
        <textarea
          className={`${inputCls} tw-min-h-[90px] tw-resize-y`}
          rows={3}
          onChange={(e) => setQuestion("others", e.target.value)}
        ></textarea>
      </QaRow>
    </div>
  );
};
export default CheckboxForm;
