const submitForm = async (formData: any) => {
  // apiv3 B2B: POST /b2b/representative/register (app-token). Hata gövdesini de döndür
  // (legacy hep res.json() okuyordu — ApiError'ı gövdeye çeviriyoruz).
  try {
    return await apiClient("/b2b/representative/register", {
      method: "POST",
      body: { params: { ssr: true, form: formData } },
    });
  } catch (e) {
    if (e instanceof ApiError) {
      return e.body ?? { success: false };
    }
    throw e;
  }
};

const emailExistsCheck = async (email: any) => {
  const result = await fetch(
    `/api/apiv2/registration_question/check?ssr=true&type=EMAIL&value=${email}`,
    {
      cache: "no-store",
      method: "GET",
    }
  );
  return result.text();
};

