import React from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCheck } from "@fortawesome/free-solid-svg-icons";

const Step4 = ({ formData }: { formData: any }) => {
  return (
    <div className="tw-mx-auto tw-max-w-xl tw-py-6 tw-text-center">
      <div className="tw-mx-auto tw-mb-4 tw-flex tw-h-16 tw-w-16 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#e8f7ee] tw-text-[#1a9c54]">
        <FontAwesomeIcon icon={faCheck} className="tw-text-2xl" />
      </div>
      <h2 className="tw-font-display tw-mb-3 tw-text-2xl tw-font-bold tw-text-[#14101c]">
        Dear {formData.name} {formData.surname},
      </h2>
      <p className="tw-m-0 tw-text-sm tw-leading-relaxed tw-text-[#5d556c]">
        Thank you for your application to be our representative office in your
        destination through TravelShop Booking website. Your registration is
        succesfully completed. We will revert back to you after a review. We
        appreciate your request for a cooperation. You have successfully
        registered to our system. Please activate your account.
      </p>
    </div>
  );
};
export default Step4;
