import * as Sentry from "@sentry/nextjs";
import React, { useEffect, useState } from "react";
import { inputCls, labelCls, pillCls } from "@/components/profile-page/fieldStyles";
import getLocations, { getCities } from "@/services/locations";

const Step1 = ({
  formData,
  onFilterChange,
}: {
  formData: any;
  onFilterChange: any;
}) => {
  const [countries, setCountries] = useState([]);
  const [selectedCountry, setSelectedCountry] = useState("");
  const [cities, setCities] = useState([]);
  useEffect(() => {
    const fetchCountries = async () => {
      try {
        setCountries((await getLocations()) || []);
      } catch (error) {
        Sentry.captureException(error);
      }
    };
    fetchCountries();
  }, []);
  useEffect(() => {
    const fetchCities = async () => {
      if (selectedCountry) {
        try {
          setCities((await getCities(selectedCountry)) || []);
        } catch (error) {
          Sentry.captureException(error);
        }
      }
    };
    fetchCities();
  }, [selectedCountry]);
  const handleCountryChange = (e: any) => {
    onFilterChange({ ...formData, country: parseInt(e.target.value) });
    setSelectedCountry(e.target.value);
  };

  const req = <span className="tw-text-[#d6336c]">*</span>;

  return (
    <div className="tw-grid tw-gap-x-8 tw-gap-y-5 md:tw-grid-cols-2">
      <div>
        <span className={labelCls}>Gender {req}</span>
        <div className="tw-flex tw-gap-2">
          {[
            { value: "male", label: "Male" },
            { value: "female", label: "Female" },
          ].map((g) => (
            <button
              type="button"
              key={g.value}
              className={pillCls(formData.gender === g.value)}
              onClick={() => onFilterChange({ ...formData, gender: g.value })}
            >
              {g.label}
            </button>
          ))}
        </div>
      </div>

      {/* spacer to keep the two-column rhythm on desktop */}
      <div className="tw-hidden md:tw-block" />

      <div>
        <label htmlFor="inputName3" className={labelCls}>
          Name {req}
        </label>
        <input
          type="text"
          className={inputCls}
          id="inputName3"
          placeholder="Name"
          onChange={(e) => {
            onFilterChange({ ...formData, name: e.target.value });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputSurname3" className={labelCls}>
          Surname {req}
        </label>
        <input
          type="text"
          className={inputCls}
          id="inputSurname3"
          placeholder="Surname"
          onChange={(e) => {
            onFilterChange({ ...formData, surname: e.target.value });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputEmailAddress3" className={labelCls}>
          Email Address {req}
        </label>
        <input
          type="email"
          className={inputCls}
          id="inputEmailAddress3"
          placeholder="Email Address"
          onChange={(e) => {
            onFilterChange({ ...formData, email: e.target.value });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputCountry3" className={labelCls}>
          Country {req}
        </label>
        <select
          className={inputCls}
          id="inputCountry3"
          value={selectedCountry}
          onChange={handleCountryChange}
        >
          <option value="">Select Country</option>
          {countries.map((country: any) => (
            <option key={country.id} value={country.id}>
              {country.name}
            </option>
          ))}
        </select>
      </div>

      <div>
        <label htmlFor="inputPassword3" className={labelCls}>
          Password {req}
        </label>
        <input
          type="password"
          className={inputCls}
          id="inputPassword3"
          placeholder="Password"
          onChange={(e) => {
            onFilterChange({ ...formData, password: e.target.value });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputCity3" className={labelCls}>
          City {req}
        </label>
        <select
          className={inputCls}
          id="inputCity3"
          onChange={(e) => {
            onFilterChange({ ...formData, city: parseInt(e.target.value) });
          }}
        >
          <option value="">Select City</option>
          {cities.map((city: any) => (
            <option key={city.id} value={city.id}>
              {city.name}
            </option>
          ))}
        </select>
      </div>

      <div>
        <label htmlFor="inputConfirmPassword3" className={labelCls}>
          Confirm Password {req}
        </label>
        <input
          type="password"
          className={inputCls}
          id="inputConfirmPassword3"
          placeholder="Confirm Password"
          onChange={(e) => {
            onFilterChange({ ...formData, confirmpassword: e.target.value });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputMobile3" className={labelCls}>
          Mobile Phone {req}
        </label>
        <input
          type="text"
          className={inputCls}
          id="inputMobile3"
          placeholder="e.g. +1 234 5678"
          onChange={(e) => {
            onFilterChange({ ...formData, phone: e.target.value });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputCode3" className={labelCls}>
          Postal Code {req}
        </label>
        <input
          type="text"
          className={inputCls}
          id="inputCode3"
          placeholder="Postal Code"
          onChange={(e) => {
            onFilterChange({ ...formData, postalcode: e.target.value });
          }}
        />
      </div>

      <div className="md:tw-col-span-2">
        <label htmlFor="inputAddress3" className={labelCls}>
          Address {req}
        </label>
        <textarea
          className={`${inputCls} tw-min-h-[90px] tw-resize-y`}
          id="inputAddress3"
          rows={3}
          onChange={(e) => {
            onFilterChange({ ...formData, address: e.target.value });
          }}
        ></textarea>
      </div>
    </div>
  );
};
export default Step1;
