import React from "react";
import { inputCls, labelCls } from "@/components/profile-page/fieldStyles";

const step2 = ({
  formData,
  onFilterChange,
}: {
  formData: any;
  onFilterChange: any;
}) => {
  const req = <span className="tw-text-[#d6336c]">*</span>;

  return (
    <div className="tw-grid tw-gap-x-8 tw-gap-y-5 md:tw-grid-cols-2">
      <div>
        <label htmlFor="inputAgency3" className={labelCls}>
          Agency Name {req}
        </label>
        <input
          type="text"
          className={inputCls}
          id="inputAgency3"
          onChange={(e) => {
            onFilterChange({ ...formData, agency_name: e.target.value });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputCode3" className={labelCls}>
          2. Person Name {req}
        </label>
        <input
          type="text"
          className={inputCls}
          id="inputCode3"
          onChange={(e) => {
            onFilterChange({
              ...formData,
              second_contact_name: e.target.value,
            });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputPosition3" className={labelCls}>
          Position/Title {req}
        </label>
        <input
          type="text"
          className={inputCls}
          id="inputPosition3"
          onChange={(e) => {
            onFilterChange({ ...formData, position: e.target.value });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputPersonSurname3" className={labelCls}>
          2. Person Surname {req}
        </label>
        <input
          type="text"
          className={inputCls}
          id="inputPersonSurname3"
          onChange={(e) => {
            onFilterChange({
              ...formData,
              second_contact_surname: e.target.value,
            });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputWebsiteAddress3" className={labelCls}>
          Website {req}
        </label>
        <input
          type="text"
          className={inputCls}
          id="inputWebsiteAddress3"
          onChange={(e) => {
            onFilterChange({ ...formData, website: e.target.value });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputPersonEmail3" className={labelCls}>
          2. Person Email {req}
        </label>
        <input
          type="email"
          className={inputCls}
          id="inputPersonEmail3"
          onChange={(e) => {
            onFilterChange({
              ...formData,
              second_contact_email: e.target.value,
            });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputOfficePhone3" className={labelCls}>
          Office Phone {req}
        </label>
        <input
          type="text"
          className={inputCls}
          id="inputOfficePhone3"
          placeholder="e.g. +1 234 5678"
          onChange={(e) => {
            onFilterChange({
              ...formData,
              officephone: e.target.value,
              fullofficephone: e.target.value,
            });
          }}
        />
      </div>

      <div>
        <label htmlFor="inputMobile3" className={labelCls}>
          2. Person Phone {req}
        </label>
        <input
          type="text"
          className={inputCls}
          id="inputMobile3"
          placeholder="e.g. +1 234 5678"
          onChange={(e) => {
            onFilterChange({
              ...formData,
              second_contact_phone: e.target.value,
            });
          }}
        />
      </div>
    </div>
  );
};
export default step2;
